package sash

import (
	"encoding/json"
	"os"
	"strings"
	"testing"

	"github.com/afterdarksys/sahinit/internal/fail"
)

// testdata/sash-mount-vectors.json was generated by sash's own
// CheckMountOpts and AllowsMountSource (internal/grant/policy.go at
// f28285b); sahinit's copy must answer the same.
func TestMountTablesMatchSash(t *testing.T) {
	raw, err := os.ReadFile("testdata/sash-mount-vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var v struct {
		Source  string   `json:"source"`
		Sources []string `json:"mount_sources"`
		Opts    []struct {
			Src  string   `json:"src"`
			Type string   `json:"type"`
			Opts []string `json:"opts"`
			Bind bool     `json:"bind"`
			Err  string   `json:"err"`
		} `json:"opts"`
		Srcs []struct {
			Src   string `json:"src"`
			Allow bool   `json:"allow"`
		} `json:"sources"`
		Forced []string `json:"forced"`
	}
	if err := json.Unmarshal(raw, &v); err != nil || v.Source == "" || len(v.Opts) < 20 {
		t.Fatalf("vectors: %v", err)
	}
	for _, c := range v.Opts {
		bind, err := CheckMountOpts(c.Src, c.Type, c.Opts)
		got := ""
		if err != nil {
			got = fail.Token(err)
		}
		if got != c.Err || err == nil && bind != c.Bind {
			t.Errorf("%s %s %s: %q bind %v, sash says %q bind %v", c.Src, c.Type, strings.Join(c.Opts, ","), got, bind, c.Err, c.Bind)
		}
	}
	g := Grant{MountSources: v.Sources}
	for _, c := range v.Srcs {
		if g.AllowsMountSource(c.Src) != c.Allow {
			t.Errorf("source %s: %v, sash says %v", c.Src, !c.Allow, c.Allow)
		}
	}
	if strings.Join(v.Forced, ",") != strings.Join(MountForcedOpts, ",") {
		t.Errorf("forced %v, sash %v", MountForcedOpts, v.Forced)
	}
}
